import { readFile } from 'node:fs/promises'
import path from 'node:path'
import { INDEXING_ENABLED, MEGA_MENU_CSS, MEGA_MENU_SRC, SITE_URL, builtPaths, canonicalUrl, href, resolvePath } from '@/lib/routes'
const MIRROR_DIR = path.join(process.cwd(), 'mirror', 'pages')
const FOOTER_PARTIAL = path.join(process.cwd(), 'mirror', 'partials', 'site-footer.html')

export const SITE_FOOTER_CSS = '/assets/site-footer/site-footer.css?v=3'
export const SITE_FOOTER_JS = '/assets/site-footer/site-footer.js?v=3'

let footerHtml: Promise<string> | undefined

/** The homepage footer (generated by scripts/build-footer.py) with links resolved for this site. */
export function getSiteFooterHtml(): Promise<string> {
  footerHtml ??= readFile(FOOTER_PARTIAL, 'utf8').then((html) =>
    // Local pages open in the same tab; only off-site links keep target="_blank".
    rewriteLinks(html).replace(/(href="\/[^"]*")\s+target="_blank"/g, '$1'),
  )
  return footerHtml
}

const LIVE_LINK = /https:\/\/studioescrow\.cloud(\/[a-z0-9-]+)(?![a-z0-9-]|\/[a-z0-9])/g

/** Root-relative page links (HTML attrs and escaped RSC props) such as "/medical-suite". */
const RELATIVE_PAGE_LINK = /(?<=href=\\?"|\\?"href\\?":\\?")(\/[a-z0-9-]+)(?=\\?")/g

/**
 * The pricing footer labels its schedule-demo link "Contact". Matches both the
 * HTML attribute and the escaped RSC payload so React props stay in sync.
 */
const FOOTER_CONTACT_LINK = /https:\/\/studioescrow\.cloud\/schedule-demo(?=\\?"(?:>|,\\?"children\\?":\\?")Contact\b)/g

const HIDDEN_HOME_SERVICES_LINK = '<a href="#" class="footer-link hide">Home Services'

/** Point links at local pages when built, otherwise at the live site. */
export function rewriteLinks(html: string): string {
  return html
    .replace(FOOTER_CONTACT_LINK, href('contact'))
    .replace(LIVE_LINK, (match, p: string) => (builtPaths.includes(p) ? p : match))
    .replace(RELATIVE_PAGE_LINK, (match, p: string) => (builtPaths.includes(p) ? match : `${SITE_URL}${p}`))
    .replace(HIDDEN_HOME_SERVICES_LINK, `<a href="${resolvePath('/home-services')}" class="footer-link hide">Home Services`)
}

/** The homepage's original footer section (static Webflow markup, no hydration). */
const HOME_FOOTER_SECTION = /<section id="footer"[\s\S]*?<\/section>/

/** Footers on the hydrated Next.js mirrors; hidden and replaced client-side after hydration. */
const HYDRATED_FOOTER = /<footer class="(?:W_qXAG|ma3IoW)_footer"/

export function rewriteMirroredHtml(html: string, pagePath: string, footerHtml: string): string {
  let out = rewriteLinks(html)
    .replace(/\/assets\/mega-menu\/mega-menu\.js(?:\?[^"'\s<>]*)?/g, MEGA_MENU_SRC)
    .replace(/\/assets\/mega-menu\/mega-menu\.css(?:\?[^"'\s<>]*)?/g, MEGA_MENU_CSS)

  const headTags = [
    `<script>window.__SE_BUILT_PATHS__=${JSON.stringify(builtPaths)};window.__SE_SITE__=${JSON.stringify(SITE_URL)}</script>`,
    `<link rel="canonical" href="${canonicalUrl(pagePath)}"/>`,
    INDEXING_ENABLED ? '' : '<meta name="robots" content="noindex, nofollow"/>',
    `<link rel="stylesheet" href="${SITE_FOOTER_CSS}"/>`,
    // In <head>, not <body>: an unexpected body element makes React discard and re-render the page.
    `<script src="${SITE_FOOTER_JS}" defer></script>`,
  ]

  if (HOME_FOOTER_SECTION.test(out)) {
    out = out.replace(HOME_FOOTER_SECTION, () => footerHtml)
  } else if (HYDRATED_FOOTER.test(out)) {
    // React would discard server-swapped markup during hydration, so site-footer.js inserts it afterwards.
    headTags.push(
      '<style>.W_qXAG_footer,.ma3IoW_footer{display:none!important}</style>',
      `<script>window.__SE_FOOTER_HTML__=${JSON.stringify(footerHtml).replace(/</g, '\\u003c')}</script>`,
    )
  }

  out = out.replace(/<head[^>]*>/i, (tag) => `${tag}${headTags.join('')}`)
  return out
}

export async function serveMirroredPage(file: string, pagePath: string): Promise<Response> {
  const [html, footerHtml] = await Promise.all([
    readFile(path.join(MIRROR_DIR, `${file}.html`), 'utf8'),
    getSiteFooterHtml(),
  ])
  return new Response(rewriteMirroredHtml(html, pagePath, footerHtml), {
    headers: { 'content-type': 'text/html; charset=utf-8' },
  })
}
